import{_ as t,o as e,c as n,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"页面置换与 working set","description":"","frontmatter":{},"headers":[],"relativePath":"os/memory/replacement.md","filePath":"os/memory/replacement.md","lastUpdated":1788475713000}'),i={name:"os/memory/replacement.md"};function o(l,a,r,p,c,d){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="页面置换与-working-set" tabindex="-1">页面置换与 working set <a class="header-anchor" href="#页面置换与-working-set" aria-label="Permalink to &quot;页面置换与 working set&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>物理 RAM 比 disk 大、但不是无限. 一旦进程需求量超过物理内存, 必须把不活跃的页 swap 到 disk. <strong>选哪页淘汰决定了&quot;无限工作负载&quot;下的有效吞吐和尾延迟</strong>. 这一章讲 LRU/LFU/ARC、working set 假说和 Linux 内核的 actual active list 机制——你会发现 DSA cache 章节里的 LRU/ARC 在 OS 层重新长出来.</p><h2 id="工作集-working-set-假说" tabindex="-1">工作集 working set 假说 <a class="header-anchor" href="#工作集-working-set-假说" aria-label="Permalink to &quot;工作集 working set 假说&quot;">​</a></h2><p>Denning 1968 提出:</p><blockquote><p>每个程序在时间 t 内访问的页面集合 W(t, Δ) 决定它能否常驻物理内存而不被 swap 频繁打扰.</p></blockquote><p>直觉:</p><ul><li>W 大 → 太多页竞争物理内存, 必然 thrashing;</li><li>W 小 → 程序在自己的话空间里跑得很好.</li></ul><p><strong>90% 的&quot;内存 thrashing&quot; 都是 W &gt; 物理内存</strong>. 这事单堆更物理 RAM 解决, 软件优化代码也会减少 W (e.g. 把循环重排到 row-major, 把指针跳改成数组扫描).</p><h2 id="lru-选页" tabindex="-1">LRU 选页 <a class="header-anchor" href="#lru-选页" aria-label="Permalink to &quot;LRU 选页&quot;">​</a></h2><p>经典 LRU: 维护&quot;最近访问时间 t&quot;, 选淘汰 t 最小者.</p><ul><li>优势: 通用, 多数负载下接近最优;</li><li>问题: <strong>被一次性扫过的 cold data 会把热点洗掉</strong>.</li></ul><p>这是 OS 内核 cache 的老问题. Linux 内核的 page cache 通过 <code>active</code> / <code>inactive</code> 两张链表 + 第二次机会算法减缓这种污染.</p><h2 id="linux-内核的-双链表第二次机会" tabindex="-1">Linux 内核的&quot;双链表第二次机会&quot; <a class="header-anchor" href="#linux-内核的-双链表第二次机会" aria-label="Permalink to &quot;Linux 内核的&quot;双链表第二次机会&quot;&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>所有可回收 page 在 inactive 或 active 链表上:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  inactive 双链表 ← 多数新页</span></span>
<span class="line"><span>  ↓ 第二次访问 with referenced bit</span></span>
<span class="line"><span>  active 双链表 ← 热点页</span></span>
<span class="line"><span>  ↓ 内存压力时 move down</span></span>
<span class="line"><span>  inactive → 由回收线程 scan 决定是否踢出</span></span></code></pre></div><p><strong>&quot;第二次机会&quot;</strong>: 一次性扫描的 cold 页访问 first time → inactive 但 (在 cache 上) referenced bit 置, 但仍然 inactive; 第二次访问才 active. 这让&quot;扫一遍大数据&quot; 不会污染 active 列表.</p><p>这个模型优化点: <strong>让热点更难进</strong>, <strong>让冷点更易被踢</strong>. <code>mm/vmscan.c</code> 的复杂度很高, 因为它要适应各种工作负载.</p><h3 id="多代-lru-mglru-6-1-的新答案" tabindex="-1">多代 LRU (MGLRU): 6.1+ 的新答案 <a class="header-anchor" href="#多代-lru-mglru-6-1-的新答案" aria-label="Permalink to &quot;多代 LRU (MGLRU): 6.1+ 的新答案&quot;">​</a></h3><p>active/inactive 双链表在大内存机器上暴露两个问题: 链表操作要拿全局锁 (跨 NUMA 扩展差), 且&quot;只看最近一次访问&quot;无法区分&quot;一分钟前&quot;和&quot;一小时前&quot;的冷度。Linux 6.1 合入的 <strong>MGLRU (multi-gen LRU)</strong> 把页按访问时间分到多个&quot;代&quot;(generation), 用<strong>访问位 + 时间分桶</strong>近似 LFU:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>generation n (最老/最冷) ← ... ← generation 0 (最新)</span></span>
<span class="line"><span>回收从最老的 generation 开始扫; 页被再访问则晋升到新 generation</span></span></code></pre></div><ul><li>每个 generation 是一次&quot;批量老化&quot;, 链表遍历换成世代轮转, 锁竞争和扫描开销都下降;</li><li>对&quot;流式扫描污染热点&quot;的防护由分代自然获得——一次性扫过的页留在同一代里被优先回收;</li><li>Chrome OS / Android 上为低内存设备设计, 后进入服务器内核; 开关 <code>/sys/kernel/mm/lru_gen/enabled</code>.</li></ul><p>工程含义: 调优老文章里的 <code>swappiness</code> 单旋钮之外, 现在还要知道 MGLRU 是否启用——两者的回收行为差异足以改变 P99 表现。</p><h2 id="lru-派生变种比较" tabindex="-1">LRU 派生变种比较 <a class="header-anchor" href="#lru-派生变种比较" aria-label="Permalink to &quot;LRU 派生变种比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>算法</th><th>思想</th><th>问题</th><th>实际用法</th></tr></thead><tbody><tr><td>LRU</td><td>最近最久未用</td><td>扫一遍污染热点</td><td>Linux page cache baseline</td></tr><tr><td>LFU</td><td>最少使用频次</td><td>老 hot 永不出去</td><td>一般结合 LRU</td></tr><tr><td>ARC (Adaptive Replacement Cache)</td><td>维护 LRU+LFU 双链表</td><td>实现复杂</td><td>ZFS, IBM DB2</td></tr><tr><td>LRU-K</td><td>根据过去 K 次访问时刻</td><td>K 选择</td><td>Postgres buffer</td></tr><tr><td>W-TinyLFU</td><td>LRU + 频次窗口分级</td><td>实现复杂</td><td>Caffeine (Java)</td></tr></tbody></table><p>Linux 内核大致是 &quot;LRU + 第二次机会 + 频次 hint&quot;; Postgres buffer 采用 Clock sweep (LRU-K 的简化); Java Caffeine 用 W-TinyLFU.</p><p><strong>这部分 DSA cache 章节也是同构</strong>: cache replacement 算法在 OS、DB、应用层、CDN 反复出现.</p><h2 id="swap-与-anon-page" tabindex="-1">swap 与 anon page <a class="header-anchor" href="#swap-与-anon-page" aria-label="Permalink to &quot;swap 与 anon page&quot;">​</a></h2><p>Linux 页分两类:</p><ol><li><strong>Anon (匿名)页</strong>: stack/heap 这类没有文件后备的内存, 回收必须写入 swap 分区/文件;</li><li><strong>File-backed 页</strong>: mmap 出来的文件内容, 直接丢弃 → 下次访问再从文件拉.</li></ol><p>file-backed page 比 anon page 回收更快 (干净页直接丢弃即可, 无需写 swap). 写 workload 持续 fsync 时, page 走 clean → dirty → writeback; dirty 积压太多会逼 kswapd 高速运转, 回收路径上的锁与 IO 直接打穿 P99 尾延迟。</p><h2 id="thrashing-监测" tabindex="-1">thrashing 监测 <a class="header-anchor" href="#thrashing-监测" aria-label="Permalink to &quot;thrashing 监测&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vmstat 1</span></span>
<span class="line"><span>watch cat /proc/vmstat | grep &#39;pgsteal\\|pgscan&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 真实 working set size 测</span></span>
<span class="line"><span>sar -B 1   # 看 pgscank/s, pgscand/s, pgsteal/s</span></span></code></pre></div><p><code>pgsteal</code> 增加 = 在淘汰; <code>pgscank</code> 增加 = 在扫 active list.</p><h2 id="page-reclaim-与-水线" tabindex="-1">page reclaim 与&quot;水线&quot; <a class="header-anchor" href="#page-reclaim-与-水线" aria-label="Permalink to &quot;page reclaim 与&quot;水线&quot;&quot;">​</a></h2><p>Linux 内核维护三道水线 (<code>/proc/sys/vm/min_free_kbytes</code> 等):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>high water  ─ ─ ─  ────  free &lt; high → kswapd 启动 pre-clean</span></span>
<span class="line"><span>low water   ─ ─ ─  ────  free &lt; low  → kswapd 进入忙碌</span></span>
<span class="line"><span>min water   ─ ─ ─  ────  free &lt; min  → 任何分配都直接同步回收</span></span></code></pre></div><p>direct reclaim = 进程自己牺牲 CPU 做回收, 损失 P99. <strong>避免 direct reclaim 是高 QPS 服务的关键技巧</strong>: 用 cgroup limit mem + 提前 warning / overcommit_ratio 合理配置.</p><h2 id="这章带走的东西" tabindex="-1">这章带走的东西 <a class="header-anchor" href="#这章带走的东西" aria-label="Permalink to &quot;这章带走的东西&quot;">​</a></h2><ul><li>working set 是软件特性, 让 OS 减低它的 W 是工程爆发点之一;</li><li>LRU / LFU / ARC 在 OS / DB / CDN 都同构;</li><li>Linux 内核 second-chance 是 LRU+hint;</li><li>双链表 active/inactive 减少 cold-scan 污染;</li><li>avoid direct reclaim 是高 QPS 服务 P99 友好的硬指标.</li></ul><p>下一节 → <a href="./allocator">内存分配器 ptmalloc/jemalloc/tcmalloc/mimalloc</a></p>`,40)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
